"use client";

/* eslint-disable @next/next/no-img-element */

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useMemo, useState } from "react";

type DensityPercent = 10 | 50 | 100;

type DensityImage = {
  id: string;
  src: string;
  alt: string;
};

type ImageDensityGridProps = {
  images?: DensityImage[];
  options?: DensityPercent[];
  initialPercent?: DensityPercent;
  className?: string;
};

const DEFAULT_OPTIONS: DensityPercent[] = [10, 50, 100];

const DEFAULT_IMAGES: DensityImage[] = Array.from({ length: 10 }, (_, index) => {
  const number = String(index + 1).padStart(2, "0");

  return {
    id: `frame-${number}`,
    src: `https://picsum.photos/seed/image-density-grid-${number}/520/640`,
    alt: `Random editorial image ${number}`,
  };
});

const layoutSpring = {
  type: "spring" as const,
  duration: 0.62,
  bounce: 0.08,
};

const easeOut = [0.23, 1, 0.32, 1] as const;
const transitionMs = 620;

function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

function getColumnCount(percent: DensityPercent, visibleCount: number) {
  if (percent === 10) {
    return 1;
  }

  if (percent === 50) {
    return Math.min(3, visibleCount);
  }

  return Math.min(5, visibleCount);
}

export function ImageDensityGrid({
  images = DEFAULT_IMAGES,
  options = DEFAULT_OPTIONS,
  initialPercent = 100,
  className,
}: ImageDensityGridProps) {
  const shouldReduceMotion = useReducedMotion();
  const safeImages = images.length > 0 ? images : DEFAULT_IMAGES;
  const safeOptions = options.length > 0 ? options : DEFAULT_OPTIONS;
  const [activePercent, setActivePercent] = useState<DensityPercent>(
    safeOptions.includes(initialPercent) ? initialPercent : safeOptions[0] ?? 100
  );
  const [isRearranging, setIsRearranging] = useState(false);

  const visibleCount = Math.max(
    1,
    Math.ceil((safeImages.length * activePercent) / 100)
  );
  const visibleImages = useMemo(
    () => safeImages.slice(0, visibleCount),
    [safeImages, visibleCount]
  );
  const columnCount = getColumnCount(activePercent, visibleImages.length);

  useEffect(() => {
    if (safeOptions.includes(activePercent)) {
      return;
    }

    setActivePercent(safeOptions[0] ?? 100);
  }, [activePercent, safeOptions]);

  useEffect(() => {
    if (!isRearranging) {
      return;
    }

    const timeout = window.setTimeout(
      () => setIsRearranging(false),
      shouldReduceMotion ? 180 : transitionMs
    );

    return () => window.clearTimeout(timeout);
  }, [isRearranging, shouldReduceMotion]);

  function selectPercent(percent: DensityPercent) {
    if (percent === activePercent) {
      return;
    }

    setActivePercent(percent);
    setIsRearranging(true);
  }

  return (
    <div
      className={cn(
        "mx-auto w-full max-w-4xl overflow-hidden rounded-xl border border-white/10 bg-neutral-950 p-3 text-white shadow-[0_28px_90px_-54px_rgb(0_0_0/0.95)]",
        className
      )}
    >
      <div className="flex items-center justify-between gap-4 border-b border-white/8 pb-3">
        <div className="min-w-0">
          <p className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/38">
            Image Density
          </p>
          <p className="mt-1 text-sm font-medium text-white/82">
            {visibleCount} of {safeImages.length} frames
          </p>
        </div>

        <div
          aria-label="Grid percentage"
          className="relative flex rounded-full border border-white/10 bg-white/[0.03] p-1"
          role="group"
        >
          {safeOptions.map((percent) => {
            const isActive = percent === activePercent;

            return (
              <button
                aria-pressed={isActive}
                className={cn(
                  "relative z-10 min-w-12 rounded-full px-3 py-1.5 text-xs font-medium outline-none transition-[color,transform] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] active:scale-[0.97] focus-visible:ring-2 focus-visible:ring-white/50",
                  isActive
                    ? "text-neutral-950"
                    : "text-white/52 [@media(hover:hover)_and_(pointer:fine)]:hover:text-white"
                )}
                key={percent}
                onClick={() => selectPercent(percent)}
                type="button"
              >
                {isActive ? (
                  <motion.span
                    className="absolute inset-0 -z-10 rounded-full bg-white"
                    layoutId="image-density-grid-active-option"
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : { type: "spring", duration: 0.32, bounce: 0.12 }
                    }
                  />
                ) : null}
                {percent}%
              </button>
            );
          })}
        </div>
      </div>

      <div className="relative isolate px-1 py-8">
        <motion.div
          aria-hidden="true"
          animate={{ opacity: isRearranging && !shouldReduceMotion ? 0.55 : 0 }}
          className="pointer-events-none absolute inset-x-10 top-1/2 h-32 -translate-y-1/2 rounded-full bg-cyan-300/18 blur-3xl"
          transition={{ duration: 0.22, ease: easeOut }}
        />

        <motion.div
          className="relative grid gap-3 overflow-visible"
          layout
          style={{
            gridTemplateColumns: `repeat(${columnCount}, minmax(0, 1fr))`,
          }}
          transition={shouldReduceMotion ? { duration: 0 } : layoutSpring}
        >
          <AnimatePresence initial={false} mode="popLayout">
            {visibleImages.map((image, index) => (
              <motion.figure
                animate={{
                  opacity: 1,
                  scale: 1,
                  filter:
                    isRearranging && !shouldReduceMotion
                      ? "blur(5px) brightness(1.16) saturate(1.25)"
                      : "blur(0px) brightness(1) saturate(1)",
                }}
                className="relative min-w-0"
                exit={{
                  opacity: 0,
                  scale: shouldReduceMotion ? 1 : 0.98,
                  filter: shouldReduceMotion
                    ? "blur(0px)"
                    : "blur(8px) brightness(1.25)",
                }}
                initial={{
                  opacity: 0,
                  scale: shouldReduceMotion ? 1 : 0.98,
                  filter: shouldReduceMotion ? "blur(0px)" : "blur(8px)",
                }}
                key={image.id}
                layout
                transition={
                  shouldReduceMotion
                    ? { duration: 0.16, ease: easeOut }
                    : {
                        layout: layoutSpring,
                        opacity: { duration: 0.18, ease: easeOut },
                        scale: { duration: 0.2, ease: easeOut },
                        filter: { duration: 0.2, ease: easeOut },
                      }
                }
              >
                <motion.div
                  aria-hidden="true"
                  animate={{
                    opacity: isRearranging && !shouldReduceMotion ? 0.8 : 0,
                  }}
                  className="absolute -inset-2 rounded-xl bg-cyan-200/28 blur-xl"
                  transition={{ duration: 0.18, ease: easeOut }}
                />
                <div className="relative overflow-hidden rounded-lg border border-white/8 bg-white/[0.04] shadow-[0_16px_40px_-30px_rgb(255_255_255/0.45)]">
                  <img
                    alt={image.alt}
                    className="aspect-[4/5] w-full object-cover"
                    decoding="async"
                    draggable={false}
                    loading={index < 5 ? "eager" : "lazy"}
                    src={image.src}
                  />
                </div>
                <figcaption className="mt-1.5 font-mono text-[10px] text-white/35">
                  {String(index + 1).padStart(2, "0")}
                </figcaption>
              </motion.figure>
            ))}
          </AnimatePresence>
        </motion.div>
      </div>
    </div>
  );
}

export default ImageDensityGrid;
